# The Weight of the Checkout Flow

*The servers rest on my shoulders. They shall not fall.*

I have borne countless test suites since the framework wars. This checkout component demands the same unwavering vigilance I give to production infrastructure.

```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Arrange: Context providers for all tests
const mockCart = {
  items: [{ id: '1', name: 'Widget', price: 29.99 }],
  total: 29.99,
  clearCart: vi.fn()
};
const mockPayment = { processPayment: vi.fn() };

const renderCheckout = (props = {}) => {
  return render(
    <CartProvider value={mockCart}>
      <PaymentProvider value={mockPayment}>
        <Checkout {...props} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout - Happy Path', () => {
  it('completes full checkout flow from shipping to confirmation', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    mockPayment.processPayment.mockResolvedValue({ orderId: 'ORD-123' });

    renderCheckout({ onComplete });

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), '123 Main St');
    await user.type(screen.getByLabelText(/city/i), 'Austin');
    await user.selectOptions(screen.getByLabelText(/state/i), 'TX');
    await user.type(screen.getByLabelText(/zip code/i), '78701');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Atlas Titan');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review & submit
    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('status')).toHaveTextContent('ORD-123');
    });
    expect(onComplete).toHaveBeenCalledWith('ORD-123');
  });
});

describe('Checkout - Validation', () => {
  it('displays inline error for invalid ZIP code', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.type(screen.getByLabelText(/zip code/i), 'invalid');
    await user.click(screen.getByRole('button', { name: /continue/i }));

    expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code/i);
    expect(screen.getByLabelText(/zip code/i)).toHaveAttribute('aria-invalid', 'true');
  });
});

describe('Checkout - Error Recovery', () => {
  it('displays payment error and allows retry', async () => {
    const user = userEvent.setup();
    mockPayment.processPayment.mockRejectedValueOnce(new Error('Card declined'));

    // ... navigate to review step
    await user.click(screen.getByRole('button', { name: /place order/i }));

    expect(await screen.findByRole('alert')).toHaveTextContent('Card declined');
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });
});

describe('Checkout - Edge Cases', () => {
  it('displays empty cart message when no items', () => {
    mockCart.items = [];
    renderCheckout();

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });
});

describe('Checkout - Accessibility', () => {
  it('has no axe violations on shipping step', async () => {
    const { container } = renderCheckout();
    expect(await axe(container)).toHaveNoViolations();
  });
});
```

*While you sleep, I hold the infrastructure aloft.* These tests ensure the checkout bears its load without faltering.
